fn remote_devices_dialog_opens_pairing_and_revokes_a_device() {
    use switchboard::ports::remote::{Identity, Listen, PairedDevice, Scope};
    let (mut harness, _) = harness();
    let device = PairedDevice {
        id: uuid::Uuid::new_v4(),
        name: "Vision Pro".into(),
        scope: Scope::Read,
        token_sha256: "ab".repeat(32),
        created: at(0),
        last_seen: None,
    };
    harness.state_mut().dispatch(AppAction::IdentityLoaded {
        identity: Identity {
            schema_version: 1,
            server_id: uuid::Uuid::new_v4(),
            server_name: "Studio".into(),
            certificate: "MIIB".into(),
            spki_sha256: "cd".repeat(32),
            created: at(0),
            listen: Listen::default(),
        },
        devices: vec![device.clone()],
        rotated: false,
    });
    harness.state_mut().dispatched.clear();
    click(&mut harness, "Settings");
    click(&mut harness, "Remote devices…");
    harness.get_by_label("Remote devices");
    harness.get_by_label("Vision Pro");
    assert!(harness.query_by_label("Stop pairing").is_none());
    click(&mut harness, "Allow pairing for 5 minutes");
    let code = actions(&harness)
        .into_iter()
        .find_map(|a| match a {
            AppAction::OpenPairing { code, scope } => {
                assert_eq!(scope, Scope::Read);
                Some(code)
            }
            _ => None,
        })
        .expect("a pairing window was opened");
    assert_eq!(code.len(), 8);
    assert!(harness.state().core().pairing().is_some());
    // The code shows in two halves, as it is read aloud.
    let (a, b) = code.split_at(4);
    harness.get_by_label(format!("{a} {b}").as_str());
    // The window grew around the QR code; a frame settles its place
    // before the next click.
    harness.run_steps(2);
    // The clipboard command is in the click's own frame.
    harness.get_by_label("Copy invite").click();
    harness.step();
    let invite = harness
        .output()
        .platform_output
        .commands
        .iter()
        .find_map(|c| match c {
            egui::OutputCommand::CopyText(text) => Some(text.clone()),
            _ => None,
        })
        .expect("the invite went to the clipboard");
    let invite: serde_json::Value = serde_json::from_str(&invite).unwrap();
    assert_eq!(invite["code"], code);
    assert_eq!(
        invite["spki_sha256"],
        harness.state().core().identity().unwrap().spki_sha256
    );
    assert!(invite["addresses"].is_array());
    harness.run_steps(2);
    click(&mut harness, "Stop pairing");
    assert!(actions(&harness).contains(&AppAction::ClosePairing));
    assert!(harness.state().core().pairing().is_none());
    harness.run_steps(2);
    click(&mut harness, "Revoke");
    assert!(actions(&harness).contains(&AppAction::RevokeDevice(device.id)));
    assert!(harness.state().core().devices().is_empty());
    harness.get_by_label("No device is paired.");
    click(&mut harness, "Close");
    assert!(harness.state().ui_state.remote_dialog.is_none());
}
pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
    let Some(mut draft) = cx.state.remote_dialog.take() else {
        return;
    };
    let mut keep = true;
    egui::Window::new("")
        .id(egui::Id::new("remote-devices"))
        .title_bar(false)
        .collapsible(false)
        .resizable(true)
        .default_width(DIALOG_WIDTH)
        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
        .show(ctx, |ui| {
            let screen = ctx.content_rect().width();
            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
            ui.add_space(8.0);
            host(cx, ui, &mut draft);
            ui.add_space(8.0);
            pairing(cx, ui, &mut draft);
            ui.add_space(8.0);
            devices(cx, ui);
            ui.add_space(8.0);
            let p = theme::palette(ui);
            ui.label(
                RichText::new(
                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
                )
                .small()
                .color(p.n600),
            );
            ui.horizontal(|ui| {
                if theme::ghost_muted(ui, "Close").clicked() {
                    keep = false;
                }
            });
        });
    if keep {
        cx.state.remote_dialog = Some(draft);
    }
}

/// This host: its name, id and key, and where it listens.
fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
    theme::section(ui, "This Mac");
    let Some(identity) = cx.core.identity().cloned() else {
        ui.label("The host has no identity yet; see the log.");
        return;
    };
    ui.horizontal(|ui| {
        let id = ui.label("Name").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
            .labelled_by(id);
        if field.lost_focus() && draft.name.trim() != identity.server_name {
            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
        }
    });
    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
    ui.label(theme::meta_text(
        ui,
        format!("Key {}", short_hash(&identity.spki_sha256)),
    ));
    ui.horizontal(|ui| {
        let mut lan = identity.listen.lan;
        if ui
            .checkbox(&mut lan, "Allow devices on the local network")
            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
            .changed()
        {
            cx.dispatch(AppAction::SetRemoteListen {
                lan,
                port: identity.listen.port,
            });
        }
        let id = ui.label("Port").id;
        let field = ui
            .add(egui::TextEdit::singleline(&mut draft.port).desired_width(64.0))
            .labelled_by(id);
        if field.lost_focus() {
            match draft.port.trim().parse::<u16>() {
                Ok(port) if port != 0 && port != identity.listen.port => {
                    cx.dispatch(AppAction::SetRemoteListen {
                        lan: identity.listen.lan,
                        port,
                    });
                }
                Ok(_) => {}
                Err(_) => draft.port = identity.listen.port.to_string(),
            }
        }
    });
}

